templates.settingsGradle:
pluginManagement {
	repositories {
		// Official NeoForged CDN: mirrors maven.neoforged.net and is reachable on networks that
		// block the main maven host. The main host is deliberately not listed: Gradle hard-fails
		// on an unreachable repository instead of falling through.
		maven { name = 'NeoForgedCDN'; url = 'https://neoforged.forgecdn.net/releases' }
		mavenCentral()
		gradlePluginPortal()
	}
}

def mcVersion = '{{mcVersion}}'
def syntheticRepo = new File(settingsDir, '.gradle/mcdeps-repo')
def minecraftDependenciesPom = new File(syntheticRepo, "net/neoforged/minecraft-dependencies/${mcVersion}/minecraft-dependencies-${mcVersion}.pom")

// NeoForged publishes net.neoforged:minecraft-dependencies:<mc> only to maven.neoforged.net. The module
// has no artifact of its own; it lists the Minecraft libraries so ModDevGradle can write the NeoForm
// runtime's artifact manifest. It is absent from every mirror, and when the manifest entry is missing
// the runtime falls back to downloading each library from maven.neoforged.net. Rebuild an equivalent
// POM from Mojang's version manifest (the same one the build downloads anyway) into a local repository,
// restricted to this machine's OS so no foreign natives are pulled. Cached under .gradle/ per version.
if (!minecraftDependenciesPom.isFile()) {
	try {
		def slurper = new groovy.json.JsonSlurper()
		def launcherManifest = slurper.parse(new URL('https://piston-meta.mojang.com/mc/game/version_manifest_v2.json'))
		def versionEntry = launcherManifest.versions.find { it.id == mcVersion }
		if (versionEntry == null) {
			throw new GradleException("Minecraft ${mcVersion} is not in Mojang's version manifest")
		}
		def versionManifest = slurper.parse(new URL(versionEntry.url as String))
		def os = org.gradle.internal.os.OperatingSystem.current()
		def osName = os.windows ? 'windows' : (os.macOsX ? 'osx' : 'linux')
		def libraries = versionManifest.libraries.findAll { lib ->
			if (lib.downloads?.artifact == null) {
				return false
			}
			if (lib.rules == null) {
				return true
			}
			boolean allowed = false
			for (def rule : lib.rules) {
				def ruleOs = rule.os
				boolean matches = ruleOs == null || ruleOs.name == null || ruleOs.name == osName
				if (matches) {
					allowed = rule.action == 'allow'
				}
			}
			return allowed
		}
		// NFRT's resolver asks for a few transitives that Mojang's manifest does not list. They must
		// be in the artifact manifest too, or NFRT downloads them from maven.neoforged.net.
		def extraLibraries = [
			'com.google.j2objc:j2objc-annotations:1.3',
		]
		def libraryNames = libraries.collect { it.name as String }
		libraryNames.addAll(extraLibraries)

		def xml = new StringBuilder()
		xml << '<?xml version="1.0" encoding="UTF-8"?>\n'
		xml << '<project xmlns="http://maven.apache.org/POM/4.0.0">\n'
		xml << '  <modelVersion>4.0.0</modelVersion>\n'
		xml << '  <groupId>net.neoforged</groupId>\n'
		xml << '  <artifactId>minecraft-dependencies</artifactId>\n'
		xml << "  <version>${mcVersion}</version>\n"
		xml << '  <packaging>pom</packaging>\n'
		xml << '  <dependencies>\n'
		for (def name in libraryNames.unique()) {
			def parts = name.split(':')
			xml << '    <dependency>\n'
			xml << "      <groupId>${parts[0]}</groupId>\n"
			xml << "      <artifactId>${parts[1]}</artifactId>\n"
			xml << "      <version>${parts[2]}</version>\n"
			if (parts.length > 3) {
				xml << "      <classifier>${parts[3]}</classifier>\n"
			}
			xml << '    </dependency>\n'
		}
		xml << '  </dependencies>\n'
		xml << '</project>\n'
		minecraftDependenciesPom.parentFile.mkdirs()
		minecraftDependenciesPom.text = xml.toString()
	} catch (Exception e) {
		logger.warn("mcmodkit: could not synthesize net.neoforged:minecraft-dependencies:${mcVersion}: ${e.message}. " +
			'If this machine can reach maven.neoforged.net, the build may still resolve the real module.')
	}
}

dependencyResolutionManagement {
	repositoriesMode = RepositoriesMode.PREFER_SETTINGS
	repositories {
		maven { name = 'NeoForgedCDN'; url = 'https://neoforged.forgecdn.net/releases' }
		mavenCentral()
		maven { name = 'MojangLibraries'; url = 'https://libraries.minecraft.net' }
		maven { name = 'SyntheticMinecraftDependencies'; url = uri(syntheticRepo) }
	}
}

rootProject.name = '{{modId}}'

templates.buildGradle:
plugins {
	id 'java-library'
	id 'net.neoforged.moddev' version '{{gradle_mdgVersion}}'
}

version = project.mod_version
group = project.mod_group_id

java.toolchain.languageVersion = JavaLanguageVersion.of({{javaVersion}})

repositories {
	mavenCentral()
}

neoForge {
	version = project.neo_version

	runs {
		client {
			client()
		}
		server {
			server()
		}
	}

	mods {
		'{{modId}}' {
			sourceSet(sourceSets.main)
		}
	}
}

tasks.withType(JavaCompile).configureEach {
	options.encoding = 'UTF-8'
}

{{DATAGEN_RUN_CONFIG}}

// NFRT recompiles Minecraft from NeoForge's userdev config, which pins exact library versions
// (for example guava 31.1-jre). Gradle's conflict resolution upgrades several of them, so those
// exact versions never reach ModDevGradle's artifact manifest, and NFRT then tries to download
// them from maven.neoforged.net - unreachable on some networks. Add the pinned coordinates to the
// manifest explicitly; transitive is off so no version conflict is reintroduced.
def nfrtPinnedLibraries = configurations.detachedConfiguration([
	'com.google.j2objc:j2objc-annotations:1.3',
	'commons-io:commons-io:2.11.0',
	'com.google.code.gson:gson:2.10',
	'com.google.errorprone:error_prone_annotations:2.11.0',
	'com.google.guava:guava:31.1-jre',
	'net.neoforged:mergetool:2.0.0:api',
	'org.checkerframework:checker-qual:3.12.0',
].collect { dependencies.create(it) } as Dependency[])
nfrtPinnedLibraries.transitive = false
tasks.matching { it.class.name.startsWith('net.neoforged.nfrtgradle.CreateMinecraftArtifacts') }.configureEach {
	addArtifactsToManifest(nfrtPinnedLibraries)
}

