templates.mainClass:
package {{packageName}};

import com.mojang.logging.LogUtils;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.ModContainer;
import net.neoforged.fml.common.Mod;
import org.slf4j.Logger;

@Mod({{mainClassSimpleName}}.MOD_ID)
public class {{mainClassSimpleName}} {
	public static final String MOD_ID = "{{modId}}";
	public static final Logger LOGGER = LogUtils.getLogger();

	public {{mainClassSimpleName}}(IEventBus modEventBus, ModContainer modContainer) {
		{{mainClassSimpleName}}Items.register(modEventBus);
		{{mainClassSimpleName}}Blocks.register(modEventBus);
{{REGISTRY_INIT_CALLS}}
		LOGGER.info("{} initialized for Minecraft {{mcVersion}}", MOD_ID);
	}

	/** Namespaced id helper. */
	public static ResourceLocation id(String path) {
		return new ResourceLocation(MOD_ID, path);
	}
}

