/** Items of {{modName}} (generated by mcmodkit). */
public final class {{mainClassSimpleName}}Items {
	public static final DeferredRegister.Items ITEMS = DeferredRegister.createItems({{mainClassSimpleName}}.MOD_ID);
	public static final DeferredRegister<CreativeModeTab> TABS =
		DeferredRegister.create(Registries.CREATIVE_MODE_TAB, {{mainClassSimpleName}}.MOD_ID);

	private static final List<Supplier<? extends ItemLike>> TAB_ENTRIES = new ArrayList<>();

	public static final ResourceKey<CreativeModeTab> TAB_KEY =
		ResourceKey.create(Registries.CREATIVE_MODE_TAB, {{mainClassSimpleName}}.id("{{modId}}"));

	public static final DeferredHolder<CreativeModeTab, CreativeModeTab> TAB = TABS.register("{{modId}}",
		() -> CreativeModeTab.builder()
			.title(Component.translatable("itemGroup.{{namespace}}"))
			.icon(() -> new ItemStack(TAB_ENTRIES.isEmpty() ? Items.STONE : TAB_ENTRIES.get(0).get()))
			.displayItems((params, output) -> {
				for (Supplier<? extends ItemLike> entry : TAB_ENTRIES) {
					output.accept(entry.get());
				}
			})
			.build());

